window.ApplicationPlan=(()=>{
 let target=null,snapshot=null,kind='all',query='',onlySelected=false;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const usd=n=>n===null?'待确认':'US$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
 function status(s){if(s.error)return s.error;if(s.running)return '正在同步 Google 日历…';if(s.needsAuthorization)return '等待 Google 日历写入授权 · 选择已保存';if(s.pending)return s.pending+' 项待同步';return s.lastSynced?'已同步 · '+new Date(s.lastSynced).toLocaleString('zh-CN'):'尚未同步';}
 function paint(){if(!target||target.dataset.applicationPlan!=="true"||!document.contains(target)||!snapshot)return;const scroll=target.querySelector('.plan-page')?.scrollTop||0,s=snapshot,t=s.totals;
 const scope=s.items.filter(i=>(!onlySelected||i.selected)&&[i.school,i.title,i.professor].join(' ').toLowerCase().includes(query.toLowerCase()));const rows=scope.filter(i=>(kind==='all'||i.kind===kind)).sort((a,b)=>Number(b.selected)-Number(a.selected)||(a.deadline||'9999-99-99').localeCompare(b.deadline||'9999-99-99')||a.school.localeCompare(b.school)||a.id.localeCompare(b.id));
 target.innerHTML=`<section class="plan-page"><div class="plan-title"><div><p class="eyebrow">FALL 2027 · ${esc(s.snapshot)}</p><h1>申请选择与费用预算</h1><p>勾选项目后同步主页倒计时与 Google 日历，取消勾选会移除对应申请日程。</p></div><button class="plan-button ${s.sync.needsAuthorization?'primary':''}" id="plan-sync">${s.sync.needsAuthorization?'授权 Google 日历写入':'立即同步日历'}</button></div>
 <div class="plan-sync-status ${s.sync.error?'error':''}" role="status">${esc(status(s.sync))} · 已选 ${s.selectedCount} 项</div>
 ${s.conflicts?.length?`<div class="plan-policy-conflicts" role="status"><strong>需择一提交：${s.conflicts.map(c=>esc(c.school)).join('、')}</strong><p>这些项目有单项目限制或共用申请流程。当前预算按候选逐项相加，择一后作为实际申请预算。</p>${s.conflicts.map(c=>`<details><summary>${esc(c.school)} · 已选 ${c.items.length} 项</summary><p>${esc(c.summary)}</p><p>${c.items.map(i=>esc(i.kind+' · '+i.title)).join('<br>')}</p><button class="plan-button compact" data-url="${esc(c.url)}">官网规则 ↗</button></details>`).join('')}</div>`:''}
 <div class="budget-cards"><div><span>原始申请费</span><strong>${usd(t.grossUsd)}</strong></div><div><span>已确认减免</span><strong>${usd(t.waivedUsd)}</strong></div><div><span>申请总预算</span><strong>${usd(t.totalUsd)}</strong><small>约 ¥${Math.round(t.totalCny).toLocaleString()} · 含额外费用</small></div></div>
 <form id="budget-form" class="budget-form"><label>USD → CNY 汇率<input type="number" step="0.0001" min="0.0001" max="10000" name="usdCny" value="${s.budget.usdCny}" required></label><label>送分 / 翻译等额外费用（USD）<input type="number" step="0.01" min="0" name="extraUsd" value="${s.budget.extraUsd}" required></label><button class="plan-button" type="submit">保存预算</button><button class="plan-button" type="button" id="latest-exchange">使用最新汇率</button><p>${s.finance.manual?"手动汇率":"最新参考汇率"} · ${esc(s.finance.asOf)} · CAD → USD ${Number(s.finance.cadUsd).toFixed(6)}。${s.finance.exchangeError?esc(s.finance.exchangeError):"启动及每6小时自动更新"}。${t.unknown?'已选项目中 '+t.unknown+' 项费用待确认，暂未计入总额。':''}</p></form>
 <div class="plan-filters"><div>${['all','PhD','MS'].map(k=>`<button class="filter-button ${kind===k?'active':''}" data-kind="${k}">${k==='all'?'全部项目':k}（${s.items.filter(i=>i.selected&&(k==='all'||i.kind===k)).length}项）</button>`).join('')}</div><input id="plan-query" placeholder="搜索学校、项目或教授" value="${esc(query)}"><label><input type="checkbox" id="only-selected" ${onlySelected?'checked':''}>只看已选</label></div>
 <p class="plan-note">截止日期采用原助手数据，具体提交时刻以项目官网为准。“已获减免”仅在你确认减免成功后勾选；建议申请 waiver 不会自动按免费计算。每个独立学位申请分别计费。</p>
 <div class="plan-table-wrap"><table class="plan-table"><thead><tr><th>申请</th><th>项目 / 学校</th><th>最终截止</th><th>费用（USD）</th><th>已获减免</th><th>学制 / 总学费</th><th>记录</th></tr></thead><tbody>${rows.map((i,index)=>`${index===0||rows[index-1].selected!==i.selected?'<tr class="plan-group"><th colspan="7">'+(i.selected?'已选择':'未选择')+' · '+rows.filter(r=>r.selected===i.selected).length+' 项</th></tr>':''}<tr class="${i.selected?'chosen':''}" data-project-id="${i.id}" data-selected="${i.selected}" data-deadline="${i.deadline}"><td><input aria-label="选择 ${esc(i.title)}" type="checkbox" data-select="${i.id}" ${i.selected?'checked':''}></td><td><span class="degree-tag">${i.kind}</span><strong>${esc(i.school)}</strong><p>${esc(i.title)}</p>${i.professor?'<small>'+esc(i.professor)+'</small>':''}${i.feeWaiver?.recommended?'<span class="waiver-mini-badge">建议waive</span>':''}</td><td>${esc(i.deadline||'待公布')}<small>${i.selected?(i.calendar?.status==='synced'?'日历已同步':i.deadline?'等待同步':'日期待确认'):''}</small></td><td><input class="fee-input" aria-label="${esc(i.school)}申请费 USD" type="number" min="0" step="0.01" placeholder="待确认" value="${i.fee.overrideUsd??i.feeUsd??''}" data-fee="${i.id}"><small>${esc(i.feeOriginal)}</small></td><td><input aria-label="${esc(i.school)}已获费用减免" type="checkbox" data-waived="${i.id}" ${i.fee.waived?'checked':''}></td><td>${i.completionCost?'<strong>约 '+window.CompletionFinance.duration(i.completionCost)+'</strong><p>总学费约 '+window.CompletionFinance.range(i.completionCost.tuitionCny)+'</p><small>毕业总花费约 '+window.CompletionFinance.range(i.completionCost.totalCny)+'</small>':'—'}</td><td><button class="plan-button compact" data-detail="${i.id}">详情</button>${i.url?'<button class="plan-button compact" data-url="'+esc(i.url)+'">申请入口 ↗</button>':''}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p class="empty-note">没有符合条件的项目。</p>'}</div></section>`;
 target.querySelector('.plan-page').scrollTop=scroll;
 target.querySelector('#plan-sync').onclick=async()=>{if(s.sync.needsAuthorization){await window.desktopAPI.authorizeCalendar();return;}await window.desktopAPI.syncApplications();refresh();};
 target.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;paint();});
 target.querySelector('#plan-query').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;paint();const q=target.querySelector('#plan-query');q.focus();q.setSelectionRange(pos,pos);};
 target.querySelector('#only-selected').onchange=e=>{onlySelected=e.target.checked;paint();};
 target.querySelectorAll('[data-select],[data-fee],[data-waived]').forEach(b=>b.onchange=async()=>{let input=b.dataset.select?{id:b.dataset.select,selected:b.checked}:b.dataset.fee?{id:b.dataset.fee,overrideUsd:b.value===''?null:Number(b.value)}:{id:b.dataset.waived,waived:b.checked};const result=await window.desktopAPI.saveApplication(input);if(result.ok===false){alert(result.error);refresh();return;}snapshot=result;paint();});
 target.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>window.ApplicationPlan.viewRecord?.(b.dataset.detail));
 target.querySelectorAll('[data-url]').forEach(b=>b.onclick=()=>window.desktopAPI.openWebsite(b.dataset.url));
 target.querySelector('#latest-exchange').onclick=async()=>{snapshot=await window.desktopAPI.saveBudget({autoExchange:true});paint();};
 target.querySelector('#budget-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),r=await window.desktopAPI.saveBudget({usdCny:Number(f.get('usdCny')),extraUsd:Number(f.get('extraUsd'))});if(r.ok===false){alert(r.error);return;}snapshot=r;paint();};
 }
 async function refresh(){snapshot=await window.desktopAPI.getApplications();window.CompletionFinance.update(snapshot);if(document.activeElement?.matches('input')&&target?.contains(document.activeElement))return;paint();}
 window.addEventListener('application-data-changed',refresh);
 return {render:node=>{target=node;node.innerHTML='<div class="empty-note">正在读取申请计划…</div>';refresh();}};
})();
